import { Button } from "@/registry/erbium/ui/button";
import { toast } from "@/registry/erbium/ui/toast";

export default function ToastActionExample() {
  return (
    <Button
      onClick={() => {
        toast.add({
          actionProps: {
            children: "Undo",
            onClick: () => {
              toast.add({ title: "Draft restored" });
            },
          },
          title: "Draft saved",
        });
      }}
    >
      Show action toast
    </Button>
  );
}
